import React from 'react';
import api from '../api';

export default function PostCard({ post, onRefresh, userId }){
  const like = async ()=>{
    try{ await api.post(`/posts/${post._id}/like`); onRefresh(); }catch(e){}
  };
  const comment = async ()=>{
    const text = prompt('Comment text');
    if (!text) return;
    await api.post(`/posts/${post._id}/comment`, { text });
    onRefresh();
  };
  const share = async () => {
    try {
      await api.post(`/posts/${post._id}/share`);
      onRefresh();
    } catch (e) {
      alert("Share failed");
    }
  };
  return (
    <div className="card">
      <div className="meta"><strong>{post.user?.username}</strong> · <small>{new Date(post.createdAt).toLocaleString()}</small></div>
      {post.mediaUrl && (post.mediaType === 'video' ? <video src={`http://localhost:5000${post.mediaUrl}`} controls width="100%" /> : <img src={`http://localhost:5000${post.mediaUrl}`} alt="" />)}
      <p>{post.caption}</p>
      <div className="actions">
        <button onClick={like}>Like ({post.likes?.length || 0})</button>
        <button onClick={comment}>Comment ({post.comments?.length || 0})</button>
        <button onClick={share}>Share ({post.shares || 0})</button>
      </div>
      <div className="comments">
        {post.comments?.map((c, idx) => <div key={idx}><small>{c.text}</small></div>)}
      </div>
    </div>
  );
}
